package com.chondrimaishrat.elearning.quiz;
import com.chondrimaishrat.elearning.course.Course; import com.chondrimaishrat.elearning.user.UserAccount; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="quiz_attempts") public class QuizAttempt { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="student_id") private UserAccount student; @ManyToOne(optional=false) @JoinColumn(name="course_id") private Course course; @Column(nullable=false) private int score; @Column(name="total_questions",nullable=false) private int totalQuestions; @Column(nullable=false) private LocalDateTime submittedAt; protected QuizAttempt(){} public QuizAttempt(UserAccount s,Course c,int score,int total){student=s;course=c;this.score=score;totalQuestions=total;submittedAt=LocalDateTime.now();} public int getScore(){return score;} public int getTotalQuestions(){return totalQuestions;} }
